 const picker=el('input');picker.type='file';picker.accept='.json,application/json';picker.disabled=!catalog||!catalog.songs.every(s=>s.jacket);picker.setAttribute('aria-label','导入本地封面 JSON');const jmsg=el('p',picker.disabled?'封面导入不可用：目录缺少已验证的 78 张封面元数据。':'本站已包含原始游戏封面；导入的本地封面仅在此页面内存中临时覆盖。');const reset=el('button','恢复内置封面');reset.type='button';const jhead=el('h3','本地封面覆盖（可选）');jacket.append(jhead,jmsg,picker,reset);
